def process(water_testing) -> pd.DataFrame:
    # Filter to Boston Harbor beaches - look for relevant keywords
    bh = water_testing[
        water_testing['Beach Name'].str.contains('Boston|Harbor|Quincy|Wollaston|Revere|Winthrop|Constitution|Pleasure|Tenean|Savin|Carson|Malibu|Nantasket|Downer|Houghs|Blacks|Sunken|Nahant', 
                                                   case=False, na=False) |
        water_testing['County Description'].str.contains('Suffolk|Norfolk', case=False, na=False)
    ]
    return bh[['Community', 'Beach Name', 'County Description', 'Beach Type Description', 'Organism']].drop_duplicates()

def process(ej_populations) -> pd.DataFrame:
    # Find communities with more than 90% EJ population
    filtered = ej_populations[ej_populations['Percent of population in EJ BGs'] > 90]
    return filtered[['Municipality', 'Percent of population in EJ BGs']].sort_values('Percent of population in EJ BGs', ascending=False)

def process(water_testing, ej_high):
    # Filter to Marine beaches with Enterococci organism
    marine_entero = water_testing[
        (water_testing['Beach Type Description'] == 'Marine') &
        (water_testing['Organism'] == 'Enterococci')
    ]
    # Join with EJ high communities (>90% EJ population)
    merged = marine_entero.merge(ej_high[['Municipality']], left_on='Community', right_on='Municipality', how='inner')
    return merged[['Community', 'Beach Name', 'County Description', 'Sample Date', 'Indicator Level']].drop_duplicates()

def process(water_testing_ej) -> pd.DataFrame:
    # Check all unique beach names and communities to identify Boston Harbor beaches
    return water_testing_ej[['Community', 'Beach Name', 'County Description']].drop_duplicates().sort_values(['Community', 'Beach Name'])

def process(bh_ej_join_rain):
    from scipy import stats
    df = bh_ej_join_rain.dropna(subset=['Indicator Level', 'Rain_3day'])
    corr, pval = stats.pearsonr(df['Rain_3day'], df['Indicator Level'])
    result = pd.DataFrame({
        'n': [len(df)],
        'pearson_r': [round(corr, 3)],
        'p_value': [pval]
    })
    return result

def load() -> pd.DataFrame:
    # Read raw lines to check if there are qualifier columns
    import subprocess
    result = subprocess.run(['head', '-5', 'data/environment/input/water-body-testing-2023.csv'], capture_output=True, text=True)
    lines = result.stdout.split('\n')
    return pd.DataFrame({'line': lines})
